"""安装布局里的资源根目录解析。

后端不能依赖 Electron 的 ``AppPaths``，因此统一按以下顺序定位
``resource/`` 目录（即 ``resources/resource``）：

1. 环境变量 ``AUTOWSGR_RESOURCE_ROOT``（Electron ``AppPaths.resourceRoot()``
   在启动后端时注入）；
2. 从当前源码文件向上回溯，命中 ``resources/resource`` 或 ``resource``。

不再内置任何开发机绝对路径（历史 ``E:\\wsgrgui\\resource`` 已移除）。
"""

from __future__ import annotations

import os
from pathlib import Path


RESOURCE_ROOT_ENV = 'AUTOWSGR_RESOURCE_ROOT'


def _normalize_resource_root(candidate: Path) -> Path | None:
    """兼容 ``resources/`` 与 ``resources/resource/`` 两种注入取值。"""
    if not candidate.is_dir():
        return None
    nested = candidate / 'resource'
    if nested.is_dir():
        return nested
    return candidate


def resolve_resource_root() -> Path | None:
    """返回可用的资源根目录；找不到时返回 ``None``。"""
    value = os.getenv(RESOURCE_ROOT_ENV, '').strip()
    if value:
        normalized = _normalize_resource_root(Path(value))
        if normalized is not None:
            return normalized

    for parent in Path(__file__).resolve().parents:
        for candidate in (parent / 'resources' / 'resource', parent / 'resource'):
            if candidate.is_dir():
                return candidate
    return None


def resource_root() -> Path:
    """返回资源根目录；未安装/未注入时抛出明确错误。"""
    root = resolve_resource_root()
    if root is None:
        raise FileNotFoundError(
            f'未找到资源目录，请设置 {RESOURCE_ROOT_ENV} 指向安装包的 resource 目录'
        )
    return root
